<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Image Preview - Delete Confirmation</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #080b12;
        --panel: #111827;
        --panel-strong: #172033;
        --text: #f8fafc;
        --muted: #b8c2d6;
        --line: #293348;
        --accent: #7dd3fc;
        --danger: #fb7185;
        --danger-strong: #e11d48;
        --shadow: 0 28px 80px rgb(0 0 0 / 0.55);
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgb(125 211 252 / 0.18), transparent 32rem),
          radial-gradient(circle at bottom right, rgb(251 113 133 / 0.13), transparent 28rem),
          var(--bg);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        border-radius: 999px;
        padding: 0.75rem 1rem;
        color: #031018;
        background: var(--accent);
        font-weight: 800;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        width: min(100% - 2rem, 72rem);
        margin: 0 auto;
        padding: 3rem 0;
      }

      header {
        margin-bottom: 2rem;
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--accent);
        font-size: 0.78rem;
        font-weight: 800;
        letter-spacing: 0.16em;
        text-transform: uppercase;
      }

      h1,
      h2,
      p {
        margin-top: 0;
      }

      h1 {
        max-width: 13ch;
        margin-bottom: 0.75rem;
        font-size: clamp(2.25rem, 8vw, 5rem);
        line-height: 0.92;
        letter-spacing: -0.06em;
      }

      .lede {
        max-width: 42rem;
        margin-bottom: 0;
        color: var(--muted);
        font-size: 1.1rem;
        line-height: 1.7;
      }

      .preview-card {
        display: grid;
        grid-template-columns: minmax(0, 1fr) minmax(16rem, 24rem);
        gap: 1.5rem;
        align-items: stretch;
        border: 1px solid rgb(255 255 255 / 0.12);
        border-radius: 2rem;
        padding: clamp(1rem, 3vw, 1.5rem);
        background: linear-gradient(145deg, rgb(17 24 39 / 0.88), rgb(15 23 42 / 0.66));
        box-shadow: var(--shadow);
      }

      figure {
        margin: 0;
      }

      .image-frame {
        overflow: hidden;
        border: 1px solid var(--line);
        border-radius: 1.5rem;
        background: #0f172a;
      }

      .image-frame img {
        display: block;
        width: 100%;
        aspect-ratio: 4 / 3;
        object-fit: cover;
      }

      .preview-card.is-deleted .image-frame img {
        filter: grayscale(1);
        opacity: 0.55;
      }

      figcaption {
        margin-top: 0.85rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .details-panel {
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        gap: 1.5rem;
        border: 1px solid var(--line);
        border-radius: 1.5rem;
        padding: 1.25rem;
        background: rgb(8 11 18 / 0.72);
      }

      .meta {
        display: grid;
        gap: 1rem;
        margin: 0;
      }

      .meta div {
        display: grid;
        gap: 0.2rem;
      }

      .meta dt {
        color: var(--muted);
        font-size: 0.78rem;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      .meta dd {
        margin: 0;
        font-size: 1rem;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
      }

      button {
        min-height: 44px;
        border: 0;
        border-radius: 999px;
        padding: 0.8rem 1.05rem;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
      }

      button:focus-visible,
      .skip-link:focus-visible {
        outline: 3px solid var(--accent);
        outline-offset: 4px;
      }

      .button-secondary {
        color: var(--text);
        background: #243047;
      }

      .button-secondary:hover {
        background: #303d57;
      }

      .trigger,
      .button-danger {
        color: #fff;
        background: linear-gradient(180deg, #fb7185, var(--danger-strong));
      }

      .trigger:hover,
      .button-danger:hover {
        background: linear-gradient(180deg, #ff8da0, #be123c);
      }

      .trigger:disabled {
        cursor: not-allowed;
        color: #d8dee9;
        background: #3b4354;
      }

      .status {
        min-height: 1.5rem;
        margin-top: 1rem;
        color: var(--muted);
      }

      dialog {
        width: min(calc(100% - 2rem), 32rem);
        border: 1px solid rgb(255 255 255 / 0.16);
        border-radius: 1.5rem;
        padding: 0;
        color: var(--text);
        background: var(--panel);
        box-shadow: var(--shadow);
      }

      dialog::backdrop {
        background: rgb(0 0 0 / 0.72);
        backdrop-filter: blur(6px);
      }

      .dialog-content {
        padding: clamp(1.25rem, 4vw, 2rem);
      }

      .dialog-icon {
        display: inline-grid;
        width: 3rem;
        height: 3rem;
        place-items: center;
        margin-bottom: 1rem;
        border-radius: 50%;
        color: #fff;
        background: rgb(225 29 72 / 0.22);
        border: 1px solid rgb(251 113 133 / 0.45);
        font-size: 1.45rem;
        font-weight: 900;
      }

      dialog h2 {
        margin-bottom: 0.6rem;
        font-size: clamp(1.5rem, 4vw, 2rem);
        letter-spacing: -0.03em;
      }

      dialog p {
        color: var(--muted);
        line-height: 1.65;
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap;
        justify-content: flex-end;
        gap: 0.75rem;
        margin-top: 1.5rem;
      }

      @media (max-width: 48rem) {
        .preview-card {
          grid-template-columns: 1fr;
        }

        .page-shell {
          padding: 2rem 0;
        }
      }

      @media (forced-colors: active) {
        body,
        .preview-card,
        .details-panel,
        dialog {
          background: Canvas;
        }

        .trigger,
        .button-danger,
        .button-secondary,
        .skip-link {
          border: 2px solid ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <main id="main-content" class="page-shell">
      <header>
        <p class="eyebrow">Library preview</p>
        <h1>Midnight coastline</h1>
        <p class="lede">
          Review this image before making changes to your collection. Deleting it removes the image from your library.
        </p>
      </header>

      <section class="preview-card" aria-labelledby="image-title">
        <figure>
          <div class="image-frame">
            <img
              src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1200 900'%3E%3Cdefs%3E%3ClinearGradient id='sky' x1='0' y1='0' x2='0' y2='1'%3E%3Cstop stop-color='%2309162e'/%3E%3Cstop offset='.56' stop-color='%231d3557'/%3E%3Cstop offset='1' stop-color='%23051118'/%3E%3C/linearGradient%3E%3CradialGradient id='moon' cx='.72' cy='.2' r='.12'%3E%3Cstop stop-color='%23f8fafc'/%3E%3Cstop offset='1' stop-color='%23bae6fd'/%3E%3C/radialGradient%3E%3C/defs%3E%3Crect width='1200' height='900' fill='url(%23sky)'/%3E%3Ccircle cx='860' cy='150' r='70' fill='url(%23moon)'/%3E%3Cpath d='M0 570 C180 500 320 620 500 548 C690 474 840 546 1020 488 C1110 458 1160 462 1200 450 L1200 900 L0 900 Z' fill='%23020617'/%3E%3Cpath d='M0 685 C180 640 310 720 480 674 C680 620 790 706 980 646 C1080 616 1150 626 1200 610 L1200 900 L0 900 Z' fill='%230b1120'/%3E%3Cpath d='M0 740 C260 700 380 790 620 735 C810 692 960 744 1200 710 L1200 900 L0 900 Z' fill='%231e293b'/%3E%3Cpath d='M690 188 l38 86 94 8 -72 62 22 92 -82 -48 -80 50 20 -94 -74 -60 94 -10z' fill='%237dd3fc' opacity='.72'/%3E%3C/svg%3E"
              alt="Illustration of a moonlit coastline with layered dark hills"
            >
          </div>
          <figcaption id="image-title">Midnight coastline, saved to your private image library.</figcaption>
        </figure>

        <aside class="details-panel" aria-label="Image details and actions">
          <dl class="meta">
            <div>
              <dt>Collection</dt>
              <dd>Travel concepts</dd>
            </div>
            <div>
              <dt>Format</dt>
              <dd>SVG preview</dd>
            </div>
            <div>
              <dt>Visibility</dt>
              <dd>Private library item</dd>
            </div>
          </dl>

          <div>
            <div class="actions">
              <button class="trigger" type="button" aria-haspopup="dialog">Delete image</button>
            </div>
            <p id="status-message" class="status" aria-live="polite"></p>
          </div>
        </aside>
      </section>
    </main>

    <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
      <form method="dialog" class="dialog-content">
        <span class="dialog-icon" aria-hidden="true">!</span>
        <h2 id="dialog-title">Delete this image?</h2>
        <p id="dialog-description">
          This will remove "Midnight coastline" from your library. This action cannot be undone.
        </p>
        <div class="dialog-actions">
          <button class="button-secondary" type="submit" value="cancel" autofocus>Cancel</button>
          <button class="button-danger" type="submit" value="delete">Delete image</button>
        </div>
      </form>
    </dialog>

    <script>
      const dialog = document.getElementById("delete-dialog");
      const trigger = document.querySelector(".trigger");
      const statusMessage = document.getElementById("status-message");
      const previewCard = document.querySelector(".preview-card");

      trigger.addEventListener("click", () => {
        dialog.showModal();
      });

      dialog.addEventListener("close", () => {
        if (dialog.returnValue !== "delete") {
          return;
        }

        previewCard.setAttribute("aria-disabled", "true");
        previewCard.classList.add("is-deleted");
        trigger.disabled = true;
        statusMessage.textContent = "Midnight coastline has been deleted from your library.";
      });
    </script>
  </body>
</html>
