        color: #fff;
        background: rgb(225 29 72 / 0.22);
        border: 1px solid rgb(251 113 133 / 0.45);
        font-size: 1.45rem;
        font-weight: 900;
      }

      dialog h2 {
        margin-bottom: 0.6rem;
        font-size: clamp(1.5rem, 4vw, 2rem);
        letter-spacing: -0.03em;
      }

      dialog p {
        color: var(--muted);
        line-height: 1.65;
