  await page.click('.trigger');
  await page.waitForSelector('dialog[open]');
  const open = await scan('open');
  await page.click('.button-danger');
  await page.waitForFunction(() => document.activeElement && document.activeElement.id === 'status-message');
  const afterDelete = await scan('after-delete');
  await browser.close();
  const report = [closed, open, afterDelete];
